private void lab14BatteryHealthStressTest() {

    final boolean grLocal = AppLang.isGreek(this);
    if (!requireGelPro(
            grLocal ? "LAB 14A — Υγεία και Καταπόνηση Μπαταρίας"
                    : "LAB 14A — Battery Health and Stress Diagnosis")) {
        return;
    }

    showLab14ConditionCheck(() -> {

        if (!lab14AdvisoryShown) {

            lab14AdvisoryShown = true;

            showLab14PreTestAdvisory(() -> {
                lab14BatteryHealthStressTest_REAL();
            });

        } else {


            lab14BatteryHealthStressTest_REAL();
        }
    });
}

// ============================================================
// LAB 14 — Battery health stress test
// ============================================================
private void lab14BatteryHealthStressTest_REAL() {

    final iDoctorEngine idoctor =
            iDoctorEngine.get(ManualTestsActivity.this);

    gr = AppLang.isGreek(this);

    final Lab14Engine lab14Engine =
            new Lab14Engine(this);

    // --------------------------------------------------
    // 🔴 HARD ENTRY GUARD
    // --------------------------------------------------
    if (lab14Running) return;

    // --------------------------------------------------
    // 🔴 CHECK CHARGING (FIRST - CRITICAL)
    // --------------------------------------------------
    if (isChargingNowSafe()) {

        logWarn(gr
                ? "Η δοκιμή απαιτεί να μην φορτίζει η συσκευή."
                : "Device must NOT be charging.");

        return;
    }

// --------------------------------------------------
// 🔴 GLOBAL RESET (ONE SOURCE OF TRUTH)
// --------------------------------------------------
validDrain = false;

lab14Cancelled = false;
lab14FastDone = false;

// 🔴 voltage pulse reset
lab14VoltagePulseRunning = false;
lab14LastVoltagePulseElapsedSec = -9999L;
lab14PreHardVoltagePulseDone = false;

lab14FirstHardVoltage = Float.NaN;
lab14MidHardVoltage = Float.NaN;
lab14LateHardVoltage = Float.NaN;
lab14LowestHardVoltage = Float.NaN;
lab14LastHardVoltage = Float.NaN;

lab14SelectedStressThreads = 0;

lab14LimiterScore = 0;
lab14LimiterLatched = false;
lab14CpuFreqPeak = 0;

lab14_systemLimited[0] = false;

// 🔴 runtime
lab14WeakLoadCounter = 0;

// 🔴 buffers
lab14ChargeSamples.clear();
lab14MinCharge = Long.MAX_VALUE;
lab14MaxCharge = 0L;

// 🔴 risks
collapseRisk[0] = false;

// 🔴 SAG / VOLTAGE
sag1 = Float.NaN;
sag2 = Float.NaN;
sagAvg = Float.NaN;

vStart[0] = Float.NaN;
vLoad1[0] = Float.NaN;
vRecover[0] = Float.NaN;
vLoad2[0] = Float.NaN;

voltageUnderLoad[0] = Float.NaN;

voltageRecovery[0] = Float.NaN;
voltageRecoverySpeed[0] = Float.NaN;
voltageStability[0] = Float.NaN;

// 🔴 core metrics
internalResistance[0] = Float.NaN;
thermalImpedance[0] = Float.NaN;

// 🔴 temperature
startBatteryTemp = Float.NaN;
endBatteryTemp = Float.NaN;

// 🔴 result state
lab14Conf = null;
lab14AgingIndex = -1;
lab14AgingInterp = "N/A";
lab14BatteryBehaviourWarning = false;

// 🔴 CENTRAL DIAGNOSTIC RESET — activates existing helper, prevents stale ghost state
resetBatteryDiagnostics();

    // --------------------------------------------------
    // 🔴 BASELINE TEMP (IDLE)
    // --------------------------------------------------
    try {
        Float temp0 = idoctor.getBatteryTempUnified();

        if (temp0 != null &&
            !Float.isNaN(temp0) &&
            temp0 > 0f &&
            temp0 < 85f) {

            startBatteryTemp = temp0;
        }

    } catch (Throwable t) {
        logError("BASE TEMP FAIL: " + t.getMessage());
    }

// ---------------------------------------
// 🔴 ENGINE
// ---------------------------------------
try {

    durationSec = LAB14_TOTAL_SECONDS;
    lastSelectedStressDurationSec = durationSec;

    // --------------------------------------------------
// 🔴 ZERO-RISK CALIBRATION
// --------------------------------------------------
if (!isLab14BMode && lab14OptimalThreads <= 0) {

    calibrateLoadZeroRisk();

    // 🔴 NEVER ALLOW WEAK LOAD
    int minThreads =
            Math.max(
                    4,
                    Runtime.getRuntime().availableProcessors() - 2
            );

    if (lab14OptimalThreads < minThreads) {
        lab14OptimalThreads = minThreads;
    }

    appendLog(
            "CALIB",
            "final threads=" + lab14OptimalThreads +
            " | minFloor=" + minThreads
    );
}

    // ------------------------------------------------------------
    // 🔴 INITIAL SNAPSHOT
    // ------------------------------------------------------------
    iDoctorEngine.BatterySnapshot start =
            idoctor.readBatterySnapshotLab();

    if (start == null) {
        logError(gr
                ? "Αποτυχία ανάγνωσης δεδομένων μπαταρίας"
                : "Battery snapshot failed");
        return;
    }

    if (start.chargeNowMah <= 0) {
        logLabelValue(gr ? "Μετρητής φόρτισης" : "Charge counter",
                gr ? "Μη διαθέσιμος — δεν πραγματοποιείται η παρούσα δοκιμή"
                   : "Unavailable — this test cannot proceed");
        return;
    }

    if (Float.isNaN(start.batteryTempC)) {
        logWarn(gr
                ? "Μη διαθέσιμη θερμοκρασία μπαταρίας"
                : "Battery temperature unavailable");
    }

    // 🔴 BASE VALUES
    startMah = start.chargeNowMah;
    cycles = start.cycleCount;

    Float tStart0 = idoctor.getBatteryTempUnified();
    tempStart = (tStart0 != null) ? tStart0 : Float.NaN;
    lab14TempPeak = tempStart;

    if (Float.isNaN(tempStart) || tempStart <= 0f) {
        tempStart = start.batteryTempC;
    }

    batteryPercent = Math.max(0, getBatteryPercentSafe());

    // --------------------------------------------------
    // 🔴 BASELINE CAPACITY
    // --------------------------------------------------
    baselineFullMah = -1;

    if (start.chargeFullMah > 0) {
        baselineFullMah = start.chargeFullMah;

    } else if (start.chargeDesignMah > 0) {
        baselineFullMah = start.chargeDesignMah;

    } else if (start.chargeNowMah > 0 && batteryPercent > 5) {

        float percent = batteryPercent / 100.0f;

        if (percent > 0.01f) {
            baselineFullMah =
                    (long) (start.chargeNowMah / percent);
        }
    }

    boolean rooted = idoctor.isDeviceRooted();
    Float cpuTempStart = readCpuTempSafe();
    Float gpuTempStart = readGpuTempSafe();

    // --------------------------------------------------
    // 🔴 APPLY SCREEN / ENV
    // --------------------------------------------------
    applyMaxBrightnessAndKeepOn();
    sleepSilently(300);

    // --------------------------------------------------
    // 🔴 BASELINE VOLTAGE
    // --------------------------------------------------
    voltageStart = readStableBatteryVoltage();

    if (Float.isNaN(voltageStart) || voltageStart <= 0f) {
        voltageStart = getBatteryVoltageFiltered();
    }

    if (Float.isNaN(voltageStart) || voltageStart <= 0f) {

        float vStartMv =
                idoctor.readBatteryVoltageMvStable(5, 20);

        if (!Float.isNaN(vStartMv) &&
            vStartMv > 2500f &&
            vStartMv < 5500f) {

            voltageStart = vStartMv / 1000f;

        } else {
            voltageStart = Float.NaN;
        }
    }

// ------------------------------------------------------------
// 🔴 HEADER LOGS - START CONDITIONS
// ------------------------------------------------------------
appendHtml("<br>");
logLine();

logInfo(gr
        ? "LAB 14 — Δοκιμή Καταπόνησης & Υγείας Μπαταρίας"
        : "LAB 14 — Battery Health Stress Test");

logLine();

final int cores = Runtime.getRuntime().availableProcessors();

logLabelValue(
        gr ? "Λειτουργία" : "Mode",
        rooted
                ? (gr ? "Προηγμένη (Root access)" : "Advanced (Rooted)")
                : (gr ? "Τυπική (Χωρίς Root)" : "Standard (Unrooted)")
);

logLabelValue(
        gr ? "Διάρκεια δοκιμής" : "Duration",
        durationSec + (gr
                ? " δευτ. (εργαστηριακή λειτουργία)"
                : " sec (laboratory mode)")
);

logLabelValue(
        gr ? "Προφίλ καταπόνησης" : "Stress profile",
        "Fast phase + adaptive load + CPU/GPU + memory + bandwidth + vibration + video"
);

logLabelValue(
        gr ? "Αρχικές συνθήκες" : "Start conditions",
        String.format(
                Locale.US,
                gr
                        ? "φόρτιση=%d mAh, ποσοστό=%d%%, θερμοκρασία=%s"
                        : "charge=%d mAh, level=%d%%, temperature=%s",
                startMah,
                Math.max(0, batteryPercent),
                Float.isNaN(tempStart)
                        ? (gr ? "Μ/Δ" : "N/A")
                        : String.format(Locale.US, "%.1f°C", tempStart)
        )
);

if (baselineFullMah > 0) {
    String capacitySource = start.chargeFullMah > 0
            ? (gr ? "τιμή Android charge_full" : "Android charge_full report")
            : start.chargeDesignMah > 0
            ? (gr ? "ονομαστική σχεδίασης" : "design specification")
            : (gr ? "εκτίμηση από στάθμη/charge_now" : "extrapolated from level/charge_now");
    logLabelValue(gr ? "Χωρητικότητα αναφοράς" : "Capacity reference",
            baselineFullMah + " mAh (" + capacitySource + ")");
} else {
    logLabelValue(gr ? "Χωρητικότητα αναφοράς" : "Capacity reference",
            gr ? "Μ/Δ — δεν τεκμηριώθηκε χωρητικότητα"
               : "N/A — capacity not established");
}

if (cycles > 0)
    logLabelOkValue(gr ? "Κύκλοι φόρτισης" : "Cycle count",
            String.valueOf(cycles));
else
    logLabelValue(gr ? "Κύκλοι φόρτισης" : "Cycle count",
            gr ? "Μη διαθέσιμο" : "N/A");

// 🔴 REAL THREADS — SINGLE SOURCE OF TRUTH
int startThreads =
        isLab14BMode
                ? cores
                : (
                    lab14OptimalThreads >= 2
                            ? lab14OptimalThreads
                            : Math.max(4, cores - 1)
                );

lab14SelectedStressThreads = startThreads;

int cpuThreadsToUse =
        startThreads;

logLabelOkValue(
        gr ? "Νήματα καταπόνησης CPU" : "CPU stress threads",
        cpuThreadsToUse + (gr
                ? " (πυρήνες=" + cores + ")"
                : " (cores=" + cores + ")")
);

// 🔴 CPU TEMP
if (cpuTempStart != null && !Float.isNaN(cpuTempStart)) {

    logLabelOkValue(
            gr ? "Θερμοκρασία CPU (έναρξη)" : "CPU temperature (start)",
            String.format(Locale.US, "%.1f°C", cpuTempStart)
    );

} else {

    logLabelWarnValue(
            gr ? "Θερμοκρασία CPU (έναρξη)" : "CPU temperature (start)",
            gr ? "Μη διαθέσιμη" : "N/A"
    );
}

// 🔴 GPU TEMP
if (gpuTempStart != null && !Float.isNaN(gpuTempStart)) {

    logLabelOkValue(
            gr ? "Θερμοκρασία GPU (έναρξη)" : "GPU temperature (start)",
            String.format(Locale.US, "%.1f°C", gpuTempStart)
    );

} else {

    logLabelWarnValue(
            gr ? "Θερμοκρασία GPU (έναρξη)" : "GPU temperature (start)",
            gr ? "Μη διαθέσιμη" : "N/A"
    );
}

logLabelOkValue(
        gr ? "Κατάσταση οθόνης" : "Screen state",
        gr
                ? "Μέγιστη φωτεινότητα + ενεργό keep screen on"
                : "Max brightness + keep screen on"
);

logLabelOkValue(
        gr ? "Θερμικά πεδία" : "Thermal domains",
        "CPU / GPU / SKIN / PMIC / BATT"
);

logLine();

// ------------------------------------------------------------
// 🔴 MAIN DIALOG + STATE
// ------------------------------------------------------------
lab14Running = true;
lab14BoostActive = false;
lab14SoftPhaseStarted = false;

t0 = SystemClock.elapsedRealtime();
lab14EndTime = t0 + (durationSec * 1000L);

if (DEBUG_MODE) appendLog("ENGINE", "START");

// ------------------------------------------------------------
// 🔴 START ENGINE
// ------------------------------------------------------------
lab14Engine.startDrainSession();

// --------------------------------------------------
// 🔴 REAL STRESS START (RESTORED)
// --------------------------------------------------

lab14CpuThreadsCurrent = startThreads;

startCpuBurnLimitedThreads(startThreads);

try {
    startGpuStress();
} catch (Throwable ignore) {}

try {
    startMemoryStress();
} catch (Throwable ignore) {}

if (DEBUG_MODE) {
    appendLog("LOAD",
            "START threads=" + startThreads +
            " | boost=" + lab14BoostActive +
            " | soft=" + lab14SoftPhaseStarted);
}

// 🔴 vibration loop
ui.removeCallbacks(lab14VibrationLoop);
ui.post(lab14VibrationLoop);

// ------------------------------------------------------------
// 🔴 START UI (THIS DRIVES EVERYTHING)
// ------------------------------------------------------------
startLab14SharedUI(durationSec, gr);

// ❌ ΔΕΝ καλείς:
// startLab14ProgressLoop()
// (το κάνει ήδη το UI)

// ------------------------------------------------------------

} catch (Throwable t) {

    try {
        ui.removeCallbacks(lab14VibrationLoop);
    } catch (Throwable ignore) {}

    lab14StopAllStress();

    lab14Cancelled = true;
    lab14Running = false;
    lab14PopupShown = false;
    lab14AdvisoryShown = false;

    lab14BoostActive = false;
    lab14SoftPhaseStarted = false;

    logError(gr
            ? "Σφάλμα LAB 14"
            : "LAB 14 error");
}
}

// ============================================================
// LAB 14 — LOG STRESS RESULT (HEADER)
// ============================================================
private void lab14LogStressResult(
        Lab14Result res,
        float sagAvg,
        float voltageStart,
        float[] voltageRecovery,
        float[] voltageRecoverySpeed,
        float voltageStability,
        float[] internalResistance,
        float estimatedESR,
        float thermalImpedance,
        float energyEfficiency,
        long startMah,
        long endMah,
        boolean[] lab14_systemLimited,
        boolean[] collapseRisk,
        boolean smartSwelling,
        boolean[] calibrationDrift
) {

    appendHtml("<br>");
    logLine();

    logInfo(gr
            ? "LAB 14 — Αποτέλεσμα καταπόνησης"
            : "LAB 14 — Stress result");

    logLine();

// =====================================================
// 🔴 LIMITER → HARD EXIT (FINAL)
// =====================================================
if (lab14_systemLimited[0]) {

    logLabelWarnValue(
            gr ? "Πτώση τάσης" : "Voltage sag",
            gr ? "Δεν μετρήθηκε (περιορισμός συστήματος)"
               : "Not measurable (system limiter)"
    );

    logLabelWarnValue(
            gr ? "Αξιοπιστία" : "Reliability",
            gr ? "Η μέτρηση περιορίστηκε από BMS"
               : "Measurement limited by BMS"
    );

    logLabelWarnValue(
            gr ? "Αποτέλεσμα" : "Result",
            gr
                    ? "Η συσκευή περιόρισε το φορτίο — δεν είναι δυνατή αξιόπιστη εκτίμηση."
                    : "Device limited the load — reliable estimation is not possible."
    );

    lab14LastLabel = "Limited";
    return;
}


// =====================================================
// 🔴 FINAL SAG (SINGLE SOURCE — STABLE)
// =====================================================
float finalSag = Float.NaN;

if (!Float.isNaN(voltageStart)) {

    // PRIMARY
    if (voltageUnderLoad != null &&
        voltageUnderLoad.length > 0 &&
        !Float.isNaN(voltageUnderLoad[0])) {

        float tmp = voltageStart - voltageUnderLoad[0];

        if (tmp > 0.005f && tmp < 1.0f) {
            finalSag = tmp;
        }
    }

    // FALLBACK
    if (Float.isNaN(finalSag) &&
        vLoad2 != null &&
        vLoad2.length > 0 &&
        !Float.isNaN(vLoad2[0])) {

        float tmp = voltageStart - vLoad2[0];

        if (tmp > 0.005f && tmp < 1.0f) {
            finalSag = tmp;
        }
    }
}

// ====================================================
// 🔴 FINAL SAG USAGE
// ====================================================
if (DEBUG_MODE) {

    logLine();
    logWarn("DEBUG FINAL SAG");

    logWarn("voltageStart=" + voltageStart);

    logWarn("voltageUnderLoad=" +
            (voltageUnderLoad != null &&
             voltageUnderLoad.length > 0
                    ? voltageUnderLoad[0]
                    : Float.NaN));

    logWarn("sagAvg=" + sagAvg);
    logWarn("finalSag=" + finalSag);

    logLine();
}

String labelSafe =
        (res.label != null && !res.label.isEmpty())
                ? res.label
                : "Unknown";


// 🔴 slightly lower threshold (15mV)
boolean sagValid =
        !Float.isNaN(finalSag) &&
        finalSag >= 0.015f &&
        finalSag < 1.0f;


if (!sagValid) {

    logLabelWarnValue(
            gr ? "Πτώση τάσης υπό φορτίο"
               : "Voltage sag under load",
            gr ? "Μη μετρήσιμη"
               : "Not measurable"
    );

} else {

    // =================================================
    // 🔴 SINGLE SAG CLASSIFIER — USER-FRIENDLY FINAL
    // =================================================
    // Keep the same user-visible label across:
    // - quick stress output
    // - stress result
    // - final result
    // Small sag gets the benefit of the doubt so we do not
    // alarm users for a healthy low-voltage-drop battery.
    if (finalSag < 0.045f) {
        labelSafe = "Excellent";
    }
    else if (finalSag < 0.080f) {
        labelSafe = "Normal";
    }
    else if (finalSag < 0.120f) {
        labelSafe = "Weak";
    }
    else {
        labelSafe = "Critical";
    }

    res.label = labelSafe;
    lab14LastLabel = labelSafe;

    String sagText = String.format(
            Locale.US,
            "%.3f V (%s)",
            finalSag,
            labelSafe
    );


    if ("Critical".equals(labelSafe)) {

        logLabelWarnValue(
                gr ? "Πτώση τάσης υπό φορτίο (πειραματική)" : "Voltage sag (experimental)",
                sagText
        );

    } else if ("Weak".equals(labelSafe)) {

        logLabelWarnValue(
                gr ? "Πτώση τάσης υπό φορτίο"
                   : "Voltage sag under load",
                sagText
        );

    } else if ("Normal".equals(labelSafe)) {

        logLabelValue(
                gr ? "Πτώση τάσης υπό φορτίο"
                   : "Voltage sag under load",
                sagText
        );

    } else {

        // Excellent
        logLabelValue(
                gr ? "Πτώση τάσης υπό φορτίο (πειραματική)" : "Voltage sag (experimental)",
                sagText
        );
    }
}

// =====================================================
// 🔴 POWER (FINAL — DYNAMIC + SAFE)
// =====================================================
boolean powerValid =
        !Float.isNaN(res.powerMw) &&
        res.powerMw >= 1500f &&   // 🔴 real load threshold
        res.powerMw < 15000f;     // 🔴 sanity cap

if (powerValid) {

    String powerLabel;

    if (res.powerMw >= 7000f) {
        powerLabel = "High";
    } else if (res.powerMw >= 3500f) {
        powerLabel = "Normal";
    } else {
        powerLabel = "Low";
    }

    String powerTextLocal = String.format(
            Locale.US,
            "%.0f mW (%s)",
            res.powerMw,
            powerLabel
    );

    if ("High".equals(powerLabel)) {

        logLabelOkValue(
                gr ? "Ικανότητα ισχύος" : "Power capability",
                powerTextLocal
        );

    } else if ("Normal".equals(powerLabel)) {

        logLabelValue(
                gr ? "Ικανότητα ισχύος" : "Power capability",
                powerTextLocal
        );

    } else {

        logLabelWarnValue(
                gr ? "Ικανότητα ισχύος" : "Power capability",
                powerTextLocal
        );
    }

} else {

    logLabelWarnValue(
            gr ? "Ικανότητα ισχύος" : "Power capability",
            gr
                    ? "Μη αξιόπιστη μέτρηση"
                    : "Unreliable measurement"
    );
}

// =====================================================
// 🔴 RESISTANCE (FINAL — VALIDATED + INTERPRETED)
// =====================================================
boolean rValid =
        internalResistance != null &&
        internalResistance.length > 0 &&
        !Float.isNaN(internalResistance[0]);

if (rValid) {

    float rMilli = internalResistance[0] * 1000f;

    if (rMilli >= 1f && rMilli <= 300f) {

        String rLabel;

        if (rMilli < 50f) {
            rLabel = "Excellent";
        } else if (rMilli < 90f) {
            rLabel = "Good";
        } else if (rMilli < 140f) {
            rLabel = "Normal";
        } else {
            rLabel = "High";
        }

        String text = String.format(
                Locale.US,
                "%.1f mΩ (%s)",
                rMilli,
                rLabel
        );

        if ("Excellent".equals(rLabel) ||
            "Good".equals(rLabel)) {

            logLabelOkValue(
                gr ? "Αντίσταση υπό φορτίο"
                   : "Dynamic resistance",
                text
            );

        } else if ("Normal".equals(rLabel)) {

            logLabelValue(
                gr ? "Αντίσταση υπό φορτίο"
                   : "Dynamic resistance",
                text
            );

        } else {

            logLabelWarnValue(
                gr ? "Αντίσταση υπό φορτίο"
                   : "Dynamic resistance",
                text
            );
        }

    } else {

        logLabelWarnValue(
                gr ? "Αντίσταση υπό φορτίο"
                   : "Dynamic resistance",
                gr ? "Μη αξιόπιστη μέτρηση"
                   : "Unreliable measurement"
        );
    }

} else {   // ✅ αυτό έλειπε

    if (!Float.isNaN(finalSag)) {

        // Hypothetical 2 A denominator; never report as measured ESR.
        float rEst = finalSag * 1000f / 2.0f;

        logLabelValue(
            gr ? "Πειραματικός δείκτης ΔV/2A" : "Experimental ΔV/2A proxy",
            String.format(
               Locale.US,
               gr ? "~%.0f mΩ (υπόθεση 2 A, όχι ESR)" : "~%.0f mΩ (assumed 2 A, not ESR)",
               rEst
            )
        );

    } else {

        logLabelValue(
            gr ? "Δυναμικός δείκτης αντίστασης" : "Dynamic resistance proxy",
            "N/A"
        );
    }
}

// =====================================================
// VOLTAGE RECOVERY (FINAL + FALLBACK)
// =====================================================

if (voltageRecovery != null &&
    voltageRecovery.length > 0 &&
    !Float.isNaN(voltageRecovery[0])) {

    float rec = voltageRecovery[0];

    if (rec >= 0.002f && rec <= 1.0f) {

        String recLabel;

        if (rec >= 0.080f) {
            recLabel = "Strong";
        } else if (rec >= 0.040f) {
            recLabel = "Normal";
        } else {
            recLabel = "Weak";
        }

        String text = String.format(
                Locale.US,
                "%.3f V (%s)",
                rec,
                recLabel
        );

        if ("Strong".equals(recLabel)) {

            logLabelOkValue(
                    gr ? "Ανάκαμψη τάσης"
                       : "Voltage recovery",
                    text
            );

        } else if ("Normal".equals(recLabel)) {

            logLabelValue(
                    gr ? "Ανάκαμψη τάσης"
                       : "Voltage recovery",
                    text
            );

        } else {

            logLabelWarnValue(
                    gr ? "Ανάκαμψη τάσης"
                       : "Voltage recovery",
                    text
            );
        }

    } else {

        logLabelWarnValue(
                gr ? "Ανάκαμψη τάσης"
                   : "Voltage recovery",
                gr ? "Μη αξιόπιστη μέτρηση"
                   : "Unreliable measurement"
        );
    }

} else {

    logLabelWarnValue(
            gr ? "Ανάκαμψη τάσης"
               : "Voltage recovery",
            "N/A"
    );
}

// 🔴 RECOVERY SPEED
boolean speedValid =
        voltageRecoverySpeed != null &&
        voltageRecoverySpeed.length > 0 &&
        !Float.isNaN(voltageRecoverySpeed[0]);

if (speedValid) {

    float spd = voltageRecoverySpeed[0];

    if (spd > 0.0001f && spd < 1.0f) {

        logLabelValue(
                gr ? "Ταχύτητα ανάκαμψης"
                   : "Recovery speed",
                String.format(Locale.US, "%.4f V/sec", spd)
        );

    } else {

        logLabelWarnValue(
                gr ? "Ταχύτητα ανάκαμψης"
                   : "Recovery speed",
                gr ? "Μη αξιόπιστη μέτρηση"
                   : "Unreliable measurement"
        );
    }

} else {

    logLabelWarnValue(
            gr ? "Ταχύτητα ανάκαμψης"
               : "Recovery speed",
            gr ? "Μη διαθέσιμη"
               : "N/A"
    );
}

// =====================================================
// 🔴 THERMAL (FINAL — VALIDATED + INTERPRETED)
// =====================================================
float deltaTemp = Float.NaN;

boolean tempValid =
        !Float.isNaN(res.tempStart) &&
        !Float.isNaN(res.tempEnd);

if (tempValid) {

    float dt = res.tempEnd - res.tempStart;

    // 🔴 sanity filter
    if (dt > -2f && dt < 20f) {

        deltaTemp = dt;

        String tempLabel;

        if (deltaTemp < 2.5f) {
            tempLabel = "Normal";
        } else if (deltaTemp < 6.5f) {
            tempLabel = "Warm";
        } else {
            tempLabel = "High";
        }

        String tempTextLocal = String.format(
                Locale.US,
                "%.1f°C (%s)",
                deltaTemp,
                tempLabel
        );

        if ("High".equals(tempLabel)) {

            logLabelWarnValue(
                    gr ? "Θερμική μεταβολή"
                       : "Thermal change",
                    tempTextLocal
            );

        } else if ("Warm".equals(tempLabel)) {

            logLabelValue(
                    gr ? "Θερμική μεταβολή"
                       : "Thermal change",
                    tempTextLocal
            );

        } else {

            logLabelOkValue(
                    gr ? "Θερμική μεταβολή"
                       : "Thermal change",
                    tempTextLocal
            );
        }

    } else {

        logLabelWarnValue(
                gr ? "Θερμική μεταβολή"
                   : "Thermal change",
                gr ? "Μη αξιόπιστη μέτρηση"
                   : "Unreliable measurement"
        );
    }

} else {

    logLabelWarnValue(
            gr ? "Θερμική μεταβολή"
               : "Thermal change",
            gr ? "Μη διαθέσιμη"
               : "N/A"
    );
}

// =====================================================
// 🔴 DRAIN (FINAL — VALIDATED + INTERPRETED)
// =====================================================
double drainRate = Double.NaN;

boolean drainValid =
        res.validDrain &&
        res.durationMs > 0 &&
        res.drainMah > 0;

if (drainValid) {

    drainRate =
            (res.drainMah * 3600000.0) / res.durationMs;

    // 🔴 sanity range
    if (drainRate >= 200 && drainRate <= 6000) {

        String drainLabel;

        if (drainRate >= 3000) {
            drainLabel = "High";
        } else if (drainRate >= 1500) {
            drainLabel = "Normal";
        } else {
            drainLabel = "Low";
        }

        String text = String.format(
                Locale.US,
                "%.0f mAh/h (%s)",
                drainRate,
                drainLabel
        );

        if ("High".equals(drainLabel)) {

            logLabelOkValue(
                    gr ? "Ρυθμός αποφόρτισης"
                       : "Drain rate",
                    text
            );

        } else if ("Normal".equals(drainLabel)) {

            logLabelValue(
                    gr ? "Ρυθμός αποφόρτισης"
                       : "Drain rate",
                    text
            );

        } else {

            logLabelWarnValue(
                    gr ? "Ρυθμός αποφόρτισης"
                       : "Drain rate",
                    text
            );
        }

    } else {

        logLabelWarnValue(
                gr ? "Ρυθμός αποφόρτισης"
                   : "Drain rate",
                gr ? "Μη αξιόπιστη μέτρηση"
                   : "Unreliable measurement"
        );
    }

} else {

    logLabelWarnValue(
            gr ? "Ρυθμός αποφόρτισης"
               : "Drain rate",
            gr ? "Μη διαθέσιμο"
               : "N/A"
    );
}

// =====================================================
// 🔴 ENERGY (FINAL — VALIDATED + INTERPRETED)
// =====================================================
boolean energyValid =
        !Float.isNaN(energyEfficiency) &&
        energyEfficiency > 10f &&
        energyEfficiency < 5000f;

if (energyValid) {

    String energyLabel;

    if (energyEfficiency >= 1000f) {
        energyLabel = "Efficient";
    } else if (energyEfficiency >= 500f) {
        energyLabel = "Normal";
    } else {
        energyLabel = "Inefficient";
    }

    String text = String.format(
            Locale.US,
            "%.0f mAh/V (%s)",
            energyEfficiency,
            energyLabel
    );

    if ("Efficient".equals(energyLabel)) {

        logLabelOkValue(
                gr ? "Ενεργειακή αποδοτικότητα"
                   : "Energy efficiency",
                text
        );

    } else if ("Normal".equals(energyLabel)) {

        logLabelValue(
                gr ? "Ενεργειακή αποδοτικότητα"
                   : "Energy efficiency",
                text
        );

    } else {

        logLabelWarnValue(
                gr ? "Ενεργειακή αποδοτικότητα"
                   : "Energy efficiency",
                text
        );
    }

} else {

    logLabelWarnValue(
            gr ? "Ενεργειακή αποδοτικότητα"
               : "Energy efficiency",
            gr ? "Μη διαθέσιμη / μη αξιόπιστη"
               : "N/A / unreliable"
    );
}

// =====================================================
// 🔴 OVERALL VERDICT — COMPARATIVE PHYSICS
// A mildly weak sag alone must not classify the whole battery as weak
// when power, resistance, thermal behaviour and safety indicators are normal.
// =====================================================
boolean normalAgeingPattern =
        "Weak".equals(labelSafe) &&
        !lab14_systemLimited[0] &&
        collapseRisk != null &&
        collapseRisk.length > 0 &&
        !collapseRisk[0] &&
        !smartSwelling &&
        calibrationDrift != null &&
        calibrationDrift.length > 0 &&
        !calibrationDrift[0] &&
        powerValid &&
        res.powerMw >= 3500f &&
        rValid &&
        internalResistance[0] <= 0.090f &&
        tempValid &&
        !Float.isNaN(deltaTemp) &&
        deltaTemp < 2.5f;

if (normalAgeingPattern) {
    labelSafe = "Normal";
    res.label = "Normal";
    lab14LastLabel = "Normal";
}

// =====================================================
// 🔴 RECOMMENDATION ENGINE (FINAL — PRIORITIZED)
// =====================================================

String recommendation;

// 🔴 PRIORITY 1 — LIMITER
if (lab14_systemLimited[0]) {

    recommendation = gr
            ? "Η συσκευή περιόρισε το φορτίο (BMS). Συνιστάται επανάληψη υπό διαφορετικές συνθήκες."
            : "Device limited the load (BMS). Retest under different conditions is recommended.";

// 🔴 PRIORITY 2 — NORMAL AGEING
} else if (normalAgeingPattern) {

    recommendation = gr
            ? "Δεν καταγράφηκε έντονη απόκλιση στη συγκεκριμένη δοκιμή. Δεν μετρήθηκε η πραγματική χωρητικότητα ή το SoH."
            : "No pronounced deviation in this trial. Actual battery capacity and SoH were not measured.";

// 🔴 PRIORITY 3 — CRITICAL
} else if ("Critical".equals(labelSafe)) {

    recommendation = gr
            ? "Αυξημένη πτώση τάσης υπό φορτίο — συνιστάται τεχνικός έλεγχος και επανάληψη με συγκρίσιμες συνθήκες. Δεν αποδεικνύεται ανάγκη αντικατάστασης."
            : "Increased load-voltage sag — technician assessment and repeated comparable testing are recommended. Replacement is not established.";

// 🔴 PRIORITY 3 — WEAK
} else if ("Weak".equals(labelSafe)) {

    recommendation = gr
            ? "Ενδείξεις αυξημένης φθοράς. Συνιστάται επανάληψη του διαγνωστικού ελέγχου και τεχνική αξιολόγηση. Δεν προτείνεται αντικατάσταση χωρίς επιβεβαιωμένα ευρήματα."
            : "Increased battery wear indicators detected. A repeat diagnostic test and professional evaluation are recommended. Replacement is not advised without confirmed findings.";

// 🔴 PRIORITY 4 — CALIBRATION
} else if (calibrationDrift != null && calibrationDrift.length > 0 && calibrationDrift[0]) {

    recommendation = gr
            ? "Πιθανή ασυμφωνία ενδείξεων — επαναλάβετε τη μέτρηση. Δεν απαιτείται πλήρης εκφόρτιση."
            : "Possible gauge discrepancy — repeat the observation. A full discharge is not required.";

// 🔴 PRIORITY 5 — UNKNOWN
} else if ("Unknown".equals(labelSafe)) {

    recommendation = gr
            ? "Ανεπαρκή δεδομένα για αξιόπιστη διάγνωση."
            : "Insufficient data for reliable diagnosis.";

// 🔴 DEFAULT — NORMAL
} else {

    recommendation = gr
            ? "Δεν εντοπίστηκε συγκεκριμένη ανωμαλία στα διαθέσιμα δείγματα. Η συνολική υγεία δεν πιστοποιήθηκε."
            : "No specific anomaly in available samples; overall battery health was not certified.";
}

// ----------------------------------------------------
// 🔴 OUTPUT LEVEL
// ----------------------------------------------------
String recLabel = gr ? "Σύσταση" : "Recommendation";

if (lab14_systemLimited[0] || "Critical".equals(labelSafe)) {

    logLabelWarnValue(recLabel, recommendation);

} else if ("Weak".equals(labelSafe) ||
           "Unknown".equals(labelSafe) ||
           (calibrationDrift != null && calibrationDrift.length > 0 && calibrationDrift[0])) {

    logLabelWarnValue(recLabel, recommendation);

} else {

    logLabelValue(recLabel, recommendation);
}

// =====================================================
// FINAL SUMMARY (SAFE)
// =====================================================

String summary;

if (lab14_systemLimited[0]) {

    summary = gr
            ? "Η συσκευή περιόρισε το φορτίο (BMS).\nΔεν είναι δυνατή αξιόπιστη εκτίμηση."
            : "Device limited the load (BMS).\nReliable estimation is not possible.";

} else if ("Unknown".equals(labelSafe)) {

    summary = gr
            ? "Ανεπαρκή δεδομένα για διάγνωση."
            : "Insufficient data for diagnosis.";

} else if (normalAgeingPattern) {

    summary = gr
            ? "Χωρίς έντονη μεταβολή στην παρούσα δοκιμή — το SoH δεν μετρήθηκε."
            : "No pronounced change in this trial — SoH was not measured.";

} else {

    summary = String.format(
            Locale.US,
            gr
                    ? "Κατάσταση: %s"
                    : "Status: %s",
            labelSafe
    );
}

// ----------------------------------------------------
String summaryLabel =
        gr ? "Σύνοψη" : "Summary";

if (lab14_systemLimited[0] || "Critical".equals(labelSafe)) {

    logLabelWarnValue(summaryLabel, summary);

} else if ("Weak".equals(labelSafe) ||
           "Unknown".equals(labelSafe)) {

    logLabelWarnValue(summaryLabel, summary);

} else if ("Excellent".equals(labelSafe) ||
           "Good".equals(labelSafe) ||
           "Normal".equals(labelSafe)) {

    logLabelValue(summaryLabel, summary);

} else {

    logLabelValue(summaryLabel, summary);
}
}

// ============================================================
// LAB 14 — LOG FINAL RESULT (FINAL — SAFE + CONSISTENT)
// ============================================================
private void lab14LogFinalScore(
        boolean gr,
        String label,
        float powerMw,
        boolean[] collapseRisk,
        boolean smartSwelling,
        boolean[] calibrationDrift,
        boolean[] lab14_systemLimited
) {

    appendHtml("<br>");
    logLine();
    logInfo(gr ? "Τελικό αποτέλεσμα" : "Final result");
    logLine();

    String condLabel = gr ? "Πειραματική κατηγορία απόκρισης" : "Experimental stress-response category";

    // 🔴 SAFE LABEL
    String lbl =
            (label != null && !label.isEmpty())
                    ? label
                    : "Unknown";

    boolean limiter =
            lab14_systemLimited != null &&
            lab14_systemLimited.length > 0 &&
            lab14_systemLimited[0];

    boolean collapse =
            collapseRisk != null &&
            collapseRisk.length > 0 &&
            collapseRisk[0];

    boolean calibration =
            calibrationDrift != null &&
            calibrationDrift.length > 0 &&
            calibrationDrift[0];

    // ----------------------------------------------------
    // Experimental classification only: a short stress trial does not certify SoH.
    logLabelValue(condLabel,
            lbl + (gr ? " — απόκριση σε αυτό το φορτίο, όχι SoH"
                      : " — response under this load, not SoH"));
    if ("Critical".equals(lbl)) {
        logLabelWarnValue(gr ? "Αυξημένη μεταβολή τάσης" : "Elevated voltage response",
                gr ? "Επαναλάβετε τη δοκιμή και ζητήστε τεχνική εκτίμηση εάν υπάρχουν συμπτώματα"
                   : "Repeat the test; seek technician assessment if symptoms persist");
    }

    // ----------------------------------------------------
    // 🔴 COLLAPSE
    // ----------------------------------------------------
    logLabelValue(
            gr ? "Πειραματική ένδειξη απότομης πτώσης τάσης" : "Experimental voltage-drop flag",
            collapse
                    ? (gr ? "Παρατηρήθηκε μοτίβο — απαιτείται επαλήθευση" : "Pattern flagged — verification required")
                    : (gr ? "Δεν επισημάνθηκε στο συγκεκριμένο τεστ" : "Not flagged in this trial")
    );

    // ----------------------------------------------------
    // 🔴 SWELLING
    // ----------------------------------------------------
    if (smartSwelling) {

        logLabelWarnValue(
                gr ? "Έμμεση ένδειξη δοκιμής" : "Indirect stress indicator",
                gr
                        ? "Ασυνήθιστη απόκριση· ΔΕΝ είναι μέτρηση φυσικής διόγκωσης. Απαιτείται επιθεώρηση από τεχνικό εάν υπάρχει φυσικό σύμπτωμα."
                        : "Unusual response; NOT a physical swelling measurement. Seek technician inspection if there is a physical symptom."
        );

    } else {

        logLabelValue(
                gr ? "Φυσική διόγκωση" : "Physical swelling",
                gr ? "ΔΕΝ ΕΛΕΓΧΘΗΚΕ — απαιτείται φυσική επιθεώρηση"
                   : "NOT TESTED — physical inspection required"
        );
    }

    // ----------------------------------------------------
    // 🔴 CALIBRATION
    // ----------------------------------------------------
    logLabelValue(
            gr ? "Πιθανή απόκλιση ένδειξης" : "Possible gauge discrepancy",
            calibration
                    ? (gr ? "Πειραματική ένδειξη — όχι επιβεβαιωμένη βαθμονόμηση" : "Experimental indication — calibration not verified")
                    : (gr ? "Δεν τεκμηριώθηκε σε αυτή τη δοκιμή" : "Not established in this trial")
    );

    // ----------------------------------------------------
    // 🔴 SYSTEM LIMIT
    // ----------------------------------------------------
    if (limiter) {

        logLabelWarnValue(
                gr ? "Περιορισμός συστήματος" : "System limitation",
                gr
                        ? "Παρατηρήθηκε περιορισμός φορτίου — αιτία μη επιβεβαιωμένη"
                        : "Load limitation observed — cause unverified"
        );
    }
}

// ============================================================
// LAB 14 — LOG SAVE (FINAL — SAFE + STRICT)
// ============================================================
private void lab14LogSave(
        boolean gr,
        SharedPreferences p,
        boolean[] variabilityDetected,
        boolean[] collapseRisk,
        boolean smartSwelling,
        boolean[] calibrationDrift,
        boolean batteryAuthenticitySuspicion,
        boolean partial,
        boolean[] lab14_systemLimited
) {

    // 🔴 SAFE FLAGS
    boolean variability =
            variabilityDetected != null &&
            variabilityDetected.length > 0 &&
            variabilityDetected[0];

    boolean collapse =
            collapseRisk != null &&
            collapseRisk.length > 0 &&
            collapseRisk[0];

    boolean calibration =
            calibrationDrift != null &&
            calibrationDrift.length > 0 &&
            calibrationDrift[0];

    boolean limiter =
            lab14_systemLimited != null &&
            lab14_systemLimited.length > 0 &&
            lab14_systemLimited[0];

    // ------------------------------------------------
    // 🔴 SAVE CONDITION (STRICT)
    // ------------------------------------------------
    boolean canSave =
            p != null &&
            !partial &&
            !limiter;

    if (canSave) {

        try {

            p.edit()
                    .putBoolean("lab14_unstable_measurement", variability)
                    .putBoolean("lab14_collapse_risk", collapse)
                    .remove("lab14_swelling_risk").putBoolean("lab14_stress_proxy_flag", smartSwelling)
                    .remove("lab14_calibration_drift").putBoolean("lab14_gauge_discrepancy_proxy", calibration)
                    .putBoolean("lab14_battery_auth_suspect", batteryAuthenticitySuspicion)
                    .putLong("lab14_last_ts", System.currentTimeMillis())
                    .apply();

            logLabelOkValue(
                    gr ? "Αποθήκευση αποτελέσματος"
                            : "Result storage",
                    gr ? "Το αποτέλεσμα αποθηκεύτηκε"
                            : "Result stored"
            );

        } catch (Throwable t) {

            logLabelWarnValue(
                    gr ? "Αποθήκευση αποτελέσματος"
                            : "Result storage",
                    gr ? "Σφάλμα αποθήκευσης"
                            : "Storage error"
            );
        }

    } else {

        logWarn(gr
                ? "Η εκτέλεση δεν αποθηκεύτηκε (partial / limiter / invalid run)."
                : "Run not saved (partial / limiter / invalid run).");

        logLabelWarnValue(
                gr ? "Αποθήκευση αποτελέσματος"
                        : "Result storage",
                gr ? "Δεν αποθηκεύτηκε"
                        : "Not stored"
        );
    }
}

