// ============================================================
// LAB 17 — AGE FORMATTER
// ============================================================
private String lab17_age(long deltaMs) {
    if (deltaMs < 0) deltaMs = 0;

    long sec = deltaMs / 1000L;
    long min = sec / 60L;
    long hr = min / 60L;

    if (hr > 0) {
        long rm = min % 60L;
        return hr + "h " + rm + "m ago";
    }

    if (min > 0) return min + "m ago";

    return Math.max(0, sec) + "s ago";
}

