// LAB 23 — Developer Options / ADB Risk Note + UI BUBBLES + AUTO-FIX HINTS
// GEL Security v3.1 (Realtime Snapshot)
// ============================================================
// ============================================================
// 1) USB DEBUGGING FLAG
// ============================================================

private void lab23DeveloperOptionsRisk() {
	
	final boolean gr = AppLang.isGreek(this);
	
	appendHtml("<br>");
    logLine();
    logInfo(gr 
            ? "LAB 23 — Κίνδυνος από επιλογές Προγραμματιστή"
            : "LAB 23 — Developer Options Status");
    logLine();

    int risk = 0;
    boolean usbDebug = false;

    try {
        int adb = Settings.Global.getInt(
                getContentResolver(),
                Settings.Global.ADB_ENABLED,
                -1
        );
        usbDebug = (adb == 1);

        if (adb < 0) {
            logLabelValue(
                    gr ? "Κατάσταση USB Debugging" : "USB Debugging status",
                    gr ? "ΑΓΝΩΣΤΗ — δεν διαβάστηκε η ρύθμιση"
                       : "UNKNOWN — setting unreadable"
            );
        } else if (usbDebug) {

            logLabelWarnValue(
                    gr ? "Κατάσταση USB Debugging" : "Status",
                    gr ? "ΕΝΕΡΓΟΠΟΙΗΜΕΝΟ"
                       : "ENABLED"
            );

            logLabelWarnValue(
                    gr ? "Κίνδυνος" : "Risk",
                    gr ? "Επιφάνεια επίθεσης με φυσική πρόσβαση"
                       : "Physical access attack surface"
            );

            risk += 30;

        } else {

            logLabelOkValue(
                    gr ? "Κατάσταση USB Debugging" : "Status",
                    gr ? "ΑΝΕΝΕΡΓΟ"
                       : "OFF"
            );
        }

    } catch (Throwable e) {

        logLabelValue(
                gr ? "USB Debugging" : "USB Debugging",
                gr ? "Αδυναμία ανάγνωσης (περιορισμός κατασκευαστή)"
                   : "Unable to read (OEM restriction)"
        );

        // Unknown setting access is not a measured security risk.
    }

// ============================================================
// 2) DEVELOPER OPTIONS FLAG
// ============================================================
boolean devOpts = false;

try {
    int dev = Settings.Global.getInt(
            getContentResolver(),
            Settings.Global.DEVELOPMENT_SETTINGS_ENABLED,
            -1
    );
    devOpts = (dev == 1);

    if (dev < 0) {
        logLabelValue(
                gr ? "Επιλογές προγραμματιστή" : "Developer options",
                gr ? "ΑΓΝΩΣΤΗ κατάσταση — δεν διαβάστηκε η ρύθμιση"
                   : "UNKNOWN status — setting unreadable"
        );
    } else if (devOpts) {

        logLabelValue(
                gr ? "Επιλογές προγραμματιστή" : "Developer options",
                gr ? "ΕΝΕΡΓΟΠΟΙΗΜΕΝΕΣ"
                   : "ENABLED"
        );

        logInfo(gr ? "Οι επιλογές προγραμματιστή δεν αποδεικνύουν από μόνες τους παραβίαση."
                   : "Developer options alone do not establish a security compromise.");

        risk += 20;

    } else {

        logLabelOkValue(
                gr ? "Επιλογές προγραμματιστή" : "Developer options",
                gr ? "ΑΝΕΝΕΡΓΕΣ"
                   : "OFF"
        );
    }

} catch (Throwable e) {

    logLabelValue(
            gr ? "Επιλογές προγραμματιστή" : "Developer options",
            gr ? "Αδυναμία ανάγνωσης"
               : "Unable to read"
    );

    // Unknown setting access is not a measured security risk.
}

// ============================================================
// 3) ADB OVER WI-FI (TCP/IP 5555)
// ============================================================
boolean adbWifi = isPortOpen(5555, 200);

if (adbWifi) {

    logLabelValue(
            gr ? "Τοπική TCP θύρα 5555" : "Local TCP port 5555",
            gr ? "Απαντά — δεν επαληθεύτηκε ότι πρόκειται για ADB"
               : "Responding — ADB service identity not verified"
    );

    logInfo(gr ? "Έλεγχος μόνο σε 127.0.0.1· δεν αποδεικνύει πρόσβαση από δίκτυο."
               : "Localhost-only probe; no external network exposure established.");

    risk += 40;

} else {

    logLabelValue(
            gr ? "Τοπική TCP θύρα 5555" : "Local TCP port 5555",
            gr ? "Δεν απαντά — η κατάσταση ασύρματου ADB παραμένει άγνωστη"
               : "Not responding — wireless ADB state remains unknown"
    );
}

// ============================================================
// 4) ADB PAIRING MODE (Wireless Debugging)
// ============================================================
// Keep quick localhost checks responsive. The wider OEM-dependent
// pairing-port probe runs off the UI thread and remains informational.
boolean adbPairing =
        isPortOpen(3700, 80) ||
        isPortOpen(7460, 80);

if (!adbPairing) {
    logInfo(gr ? "Πρόσθετη τοπική σάρωση θυρών στο παρασκήνιο..."
               : "Additional local port check running asynchronously...");
    new Thread(() -> {
        boolean extraResponded = scanPairingPortRange();
        runOnUiThread(() -> {
            if (isFinishing() || isDestroyed()) return;
            logLabelValue(
                    gr ? "Πρόσθετες τοπικές θύρες" : "Additional local ports",
                    extraResponded
                            ? (gr ? "Βρέθηκε ανταποκρινόμενη TCP θύρα· η υπηρεσία δεν ταυτοποιήθηκε"
                                  : "A TCP port responded; service identity not verified")
                            : (gr ? "Δεν απάντησε καμία από τις δοκιμασμένες θύρες· Wireless debugging άγνωστο"
                                  : "No probed port responded; wireless debugging status unknown")
            );
        });
    }, "GEL-Lab23-PortProbe").start();
}

if (adbPairing) {

    logLabelValue(
            gr ? "Δοκιμασμένες τοπικές θύρες" : "Probed local ports",
            gr ? "Κάποια θύρα απαντά — δεν ταυτοποιήθηκε υπηρεσία ADB"
               : "A port responded — no ADB service identity verified"
    );

    logInfo(gr ? "Δεν ελέγχθηκε εξωτερική ανιχνευσιμότητα ή εξουσιοδότηση ADB."
               : "External discoverability or ADB authorization was not tested.");

    risk += 25;

} else {

    logLabelValue(
            gr ? "Δοκιμασμένες τοπικές θύρες" : "Probed local ports",
            gr ? "Οι αρχικές θύρες δεν απάντησαν· εκκρεμεί πρόσθετη τοπική σάρωση"
               : "Initial ports did not respond; additional local probe pending"
    );
}

// ============================================================
// 5) EVIDENCE LIMITS — NO ARBITRARY WHOLE-DEVICE SCORE
// ============================================================
logInfo(gr ? "Δεν υπολογίζεται ποσοστό ασφάλειας από flags και τοπικές TCP θύρες."
           : "No whole-device security percentage from flags or localhost TCP probes.");

// ============================================================
// 6) ACTION RECOMMENDATIONS
// ============================================================
appendHtml("<br>");
logInfo(gr ? "Προτεινόμενες ενέργειες"
           : "Recommended actions");
           logLine();

if (usbDebug) {
    logLabelWarnValue(
            "USB Debugging",
            gr ? "Είναι ενεργό — απενεργοποιήστε το αν δεν το χρειάζεστε"
               : "Enabled — turn off when it is no longer needed"
    );
} else {
    logLabelValue("USB Debugging",
            gr ? "Δηλώθηκε ανενεργό ή μη αναγνώσιμο — δεν αποτελεί έλεγχο όλων των ADB διαδρομών"
               : "Reported off or unreadable — not verification of every ADB path");
}
if (devOpts) {
    logInfo(gr ? "Οι επιλογές προγραμματιστή μπορούν να παραμείνουν ενεργές για νόμιμη χρήση."
               : "Developer options may be enabled for legitimate use.");
}

if (adbWifi || adbPairing) {
    logInfo(gr ? "Ελέγξτε την πραγματική ρύθμιση Wireless debugging στις Ρυθμίσεις Android."
               : "Check actual Wireless debugging in Android Settings.");
} else {
    logInfo(gr ? "Οι τοπικές δοκιμές θυρών δεν τεκμηριώνουν απενεργοποιημένο ADB."
               : "Local port probes do not prove that wireless ADB is off.");
}

logInfo(gr ? "Σύνοψη: τα στοιχεία αφορούν ρυθμίσεις, όχι τεχνική πιστοποίηση ασφάλειας."
           : "Summary: observed settings, not device-security certification.");

appendHtml("<br>");
logOk(gr ? "Το Lab 23 ολοκληρώθηκε (έλεγχος προσβάσιμων ρυθμίσεων)."
         : "Lab 23 finished (accessible-settings check).");
logLine();
}


// ============================================================
// UI BUBBLES (GEL)
// ============================================================
private String bubble(boolean on) {
    return on ? "[ON]" : "[OFF]";
}

private String riskBubble(int risk) {
    if (risk <= 10) return "[LOW]";
    if (risk <= 30) return "[MEDIUM]";
    if (risk <= 60) return "[HIGH]";
    return "[CRITICAL]";
}

// ============================================================
// HELPERS — PORT CHECK (LOCALHOST)
// ============================================================
private boolean isPortOpen(int port, int timeoutMs) {
Socket s = null;
try {
s = new Socket();
s.connect(new InetSocketAddress("127.0.0.1", port), timeoutMs);
return true;
} catch (Exception e) {
return false;
} finally {
if (s != null) try { s.close(); } catch (Exception ignored) {}
}
}

// Scan pairing port range 7460-7490 (best-effort)
private boolean scanPairingPortRange() {
for (int p = 7460; p <= 7490; p++) {
if (isPortOpen(p, 80)) return true;
}
return false;
}

// ============================================================
// LAB 24 — Root / Bootloader Suspicion Checklist (FULL AUTO + RISK SCORE)
// GEL Universal Edition — NO external libs
// ============================================================
private void lab24RootSuspicion() {

    final boolean gr = AppLang.isGreek(this);

    appendHtml("<br>");
    logLine();
    logInfo(gr
            ? "LAB 24 — Έλεγχος Root / Ακεραιότητας Bootloader (ΑΥΤΟΜΑΤΟ)."
            : "LAB 24 — Root / Bootloader Integrity Scan (AUTO).");
    logLine();

// ---------------------------  
// (1) ROOT DETECTION  
// ---------------------------  
int rootScore = 0;  
List<String> rootFindings = new ArrayList<>();  

// su / busybox paths  
String[] suPaths = {  
        "/system/bin/su",  
        "/system/xbin/su",  
        "/sbin/su",  
        "/su/bin/su",  
        "/system/bin/busybox",  
        "/system/xbin/busybox",  
        "/vendor/bin/su",  
        "/odm/bin/su"  
};  

boolean suFound = false;  

for (String p : suPaths) {  
    if (lab24_fileExists(p)) {  
        suFound = true;  
        rootScore += 18;  
        rootFindings.add("su/busybox path found: " + p);  
    }  
}  

// which su (best-effort, avoid false positives)  
String whichSu = lab24_execFirstLine("which su");
if (whichSu != null &&
    (whichSu.contains("/system/xbin/") ||
     whichSu.contains("/su/"))) {

    rootScore += 12;
    rootFindings.add("'which su' returned: " + whichSu);
    suFound = true;
}

// try exec su (strong indicator)  
boolean suExec = lab24_canExecSu();  
if (suExec) {  
    rootScore += 25;  
    rootFindings.add("su execution possible (shell granted).");  
    suFound = true;  
}  

// known root packages  
String[] rootPkgs = {  
        "com.topjohnwu.magisk",  
        "eu.chainfire.supersu",  
        "com.koushikdutta.superuser",  
        "com.noshufou.android.su",  
        "com.kingroot.kinguser",  
        "com.kingo.root",  
        "com.saurik.substrate",  
        "de.robv.android.xposed.installer"  
};  

List<String> installed = lab24_getInstalledPackagesLower();  
boolean pkgHit = false;  

for (String rp : rootPkgs) {  
    if (installed.contains(rp)) {  
        pkgHit = true;  
        rootScore += 20;  
        rootFindings.add("root package installed: " + rp);  
    }  
}  

// build tags  
    try {

    String tags = Build.TAGS;

    if (tags != null && tags.contains("test-keys")) {

        rootFindings.add("Build.TAGS contains test-keys.");

        // only increase score if other root signals exist
        if (suFound || pkgHit) {
            rootScore += 10;
        }
    }

} catch (Throwable ignore) {}

// suspicious system properties  
String roSecure = lab24_getProp("ro.secure");  
String roDebug  = lab24_getProp("ro.debuggable");  

if ("0".equals(roSecure)) {  
    rootScore += 18;  
    rootFindings.add("ro.secure=0 (insecure build).");  
}  
if ("1".equals(roDebug)) {  
    rootScore += 12;  
    rootFindings.add("ro.debuggable=1 (debuggable build).");  
}  

// ---------------------------  
// (2) BOOTLOADER / VERIFIED BOOT  
// ---------------------------  
int blScore = 0;  
List<String> blFindings = new ArrayList<>();  

String vbState = lab24_getProp("ro.boot.verifiedbootstate"); // green/yellow/orange/red  
String vbmeta  = lab24_getProp("ro.boot.vbmeta.device_state"); // locked/unlocked  
String flashL  = lab24_getProp("ro.boot.flash.locked"); // 1/0  
String wlBit   = lab24_getProp("ro.boot.warranty_bit"); // 0/1 (OEM)  

if (vbState != null) {

    String v = vbState.toLowerCase(Locale.US);

    if (v.contains("orange") ||
        v.contains("yellow") ||
        v.contains("red")) {

        blScore += 30;
        blFindings.add("VerifiedBootState=" + vbState);
    } else {
        blFindings.add("VerifiedBootState=" + vbState);
    }
}

if (vbmeta != null && vbmeta.contains("unlocked")) {  
    blScore += 35;  
    blFindings.add("vbmeta.device_state=unlocked");  
} else if (vbmeta != null) {  
    blFindings.add("vbmeta.device_state=" + vbmeta);  
}  

if ("0".equals(flashL)) {  
    blScore += 25;  
    blFindings.add("flash.locked=0 (bootloader unlocked).");  
} else if (flashL != null) {  
    blFindings.add("flash.locked=" + flashL);  
}  

if ("1".equals(wlBit)) {  
    blScore += 15;  
    blFindings.add("warranty_bit=1 (tamper flag).");  
}  

// OEM unlock allowed (settings)  
try {  
    int oemAllowed =  
            Settings.Global.getInt(  
                    getContentResolver(),  
                    "oem_unlock_allowed",  
                    0  
            );  
    if (oemAllowed == 1) {  
        blScore += 10;  
        blFindings.add("OEM unlock allowed=1 (developer enabled).");  
    }  
} catch (Throwable ignore) {}  

// /proc/cmdline hints  
String cmdline = lab24_readOneLine("/proc/cmdline");  
if (cmdline != null) {  
    String c = cmdline.toLowerCase(Locale.US);  
    if (c.contains("verifiedbootstate=orange") ||  
        c.contains("verifiedbootstate=yellow") ||  
        c.contains("vbmeta.device_state=unlocked") ||  
        c.contains("bootloader=unlocked")) {  
        blScore += 20;  
        blFindings.add("/proc/cmdline reports unlocked / weak verified boot.");  
    }  
}  

// ---------------------------  
// (3) BOOT ANIMATION / SPLASH MOD  
// ---------------------------  
int animScore = 0;  
List<String> animFindings = new ArrayList<>();  

if (lab24_fileExists("/data/local/bootanimation.zip")) {  
    animScore += 35;  
    animFindings.add("Custom bootanimation: /data/local/bootanimation.zip");  
}  

boolean sysBoot =
        lab24_fileExists("/system/media/bootanimation.zip") ||
        lab24_fileExists("/product/media/bootanimation.zip") ||
        lab24_fileExists("/oem/media/bootanimation.zip") ||
        lab24_fileExists("/vendor/media/bootanimation.zip") ||
        lab24_fileExists("/system_ext/media/bootanimation.zip");

if (!sysBoot) {  
    animScore += 15;  
    animFindings.add("No stock bootanimation found (possible custom ROM).");  
} else {  
    animFindings.add("Stock bootanimation path exists.");  
}  

// ---------------------------  
// FINAL RISK SCORE  
// ---------------------------  
int magiskStealthScore = 0;
List<String> magiskStealthFindings = new ArrayList<>();

try {
    magiskStealthScore = lab24_magiskStealthScore(magiskStealthFindings);
} catch (Throwable ignore) {}

int risk =
        rootScore +
        blScore +
        animScore +
        Math.min(15, magiskStealthScore / 3);

// ------------------------------------------------
// VERIFIED SECURITY BONUS
// ------------------------------------------------
if ("green".equals(vbState)) {
    risk -= 8;
}

if ("locked".equals(vbmeta)) {
    risk -= 8;
}

if ("1".equals(flashL)) {
    risk -= 6;
}

// never below zero
risk = Math.max(0, Math.min(100, risk));

logInfo(gr ? "Έλεγχος Root:" : "Root Scan:");  
if (rootFindings.isEmpty()) {  
    logInfo(gr ? "Δεν παρατηρήθηκαν ισχυρά root ίχνη· η απουσία τους δεν αποδεικνύει unrooted."
               : "No strong root traces observed; their absence does not prove unrooted.");  
} else {  
    for (String s : rootFindings)
        logWarn("• " + s);  
}  

logInfo(gr ? "Bootloader / Verified Boot:"
           : "Bootloader / Verified Boot:");

if (blFindings.isEmpty()) {

    logInfo(gr ? "Δεν υπάρχουν αναγνώσιμα στοιχεία bootloader/Verified Boot."
               : "No readable bootloader/Verified Boot data.");

} else {

    for (String s : blFindings) {

        String l = s.toLowerCase(Locale.US);

        if (l.contains("verifiedbootstate=green") ||
            l.contains("vbmeta.device_state=locked") ||
            l.contains("flash.locked=1")) {

            logInfo("• " + s);

        } else {

            logWarn("• " + s);
        }
    }
}

logInfo(gr ? "Boot Animation / Splash:"
           : "Boot Animation / Splash:");  
if (animFindings.isEmpty()) {

    logInfo(gr ? "Δεν παρατηρήθηκαν ορατές διαδρομές boot animation."
               : "No visible boot-animation paths observed.");

} else {

    for (String s : animFindings) {

        String l = s.toLowerCase(Locale.US);

        if (l.contains("stock bootanimation")) {

            logInfo("• " + s);

        } else {

            logWarn("• " + s);
        }
    }
}

logInfo(gr ? "Magisk / Stealth heuristics:"
           : "Magisk / Stealth heuristics:");

if (magiskStealthFindings.isEmpty()) {

    logInfo(gr ? "Δεν εντοπίστηκαν ισχυρά ίχνη stealth root στους προσβάσιμους ελέγχους."
               : "No strong stealth-root traces seen in accessible checks.");

} else {

    for (String s : magiskStealthFindings) {

        String l = s.toLowerCase(Locale.US);

        if ((l.contains("/debug_ramdisk") ||
             l.contains("overlay mount")) &&
            "green".equals(vbState) &&
            "locked".equals(vbmeta) &&
            "1".equals(flashL)) {

            logInfo("• " + s);

        } else {

            logWarn("• " + s);
        }
    }
}

// ------------------------------------------------------------
// ROOT / VERIFIED BOOT — EVIDENCE, NOT FABRICATED SECURITY PERCENTAGE
// ------------------------------------------------------------
// The legacy path, bootanimation and property counters are not physically
// calibrated. Keep every probe above; never use the sum to certify safety.
appendHtml("<br>");
logInfo(gr ? "Σύνοψη τεκμηρίωσης Root / Verified Boot"
           : "Root / Verified Boot evidence summary");

if (suExec) {
    logLabelWarnValue(gr ? "Πρόσβαση root" : "Root access",
            gr ? "Εκτελέστηκε su με uid=0 — προνομιούχο shell επιβεβαιώθηκε"
               : "su returned uid=0 — privileged shell confirmed");
} else if (suFound || pkgHit || !magiskStealthFindings.isEmpty()) {
    logLabelWarnValue(gr ? "Ενδείξεις root" : "Root indicators",
            gr ? "Βρέθηκαν ίχνη, αλλά δεν επιβεβαιώθηκε εκτέλεση root shell"
               : "Indicators observed, but root-shell execution not confirmed");
} else {
    logLabelValue(gr ? "Ενδείξεις root" : "Root indicators",
            gr ? "Δεν εντοπίστηκαν στους προσβάσιμους ελέγχους· κατάσταση root άγνωστη"
               : "None found in accessible checks; rootedness unverified");
}

boolean bootFailed = "red".equals(vbState);
boolean bootUnlocked = "orange".equals(vbState)
        || "unlocked".equals(vbmeta) || "0".equals(flashL);
if (bootFailed) {
    logLabelErrorValue(gr ? "Verified Boot" : "Verified Boot",
            gr ? "Το Android αναφέρει RED — απαιτείται έλεγχος της εκκίνησης"
               : "Android reports RED — investigate boot verification");
} else if (bootUnlocked) {
    logLabelWarnValue(gr ? "Bootloader / Verified Boot" : "Bootloader / Verified Boot",
            gr ? "Το Android αναφέρει ξεκλείδωτη κατάσταση· δεν αποδεικνύει root"
               : "Android reports an unlocked state; this does not prove root");
} else if ("yellow".equals(vbState)) {
    logLabelValue(gr ? "Verified Boot" : "Verified Boot",
            gr ? "YELLOW: αναφερόμενη προσαρμοσμένη ρίζα εμπιστοσύνης· κατάσταση root άγνωστη"
               : "YELLOW: custom root of trust reported; root status unknown");
} else if ("green".equals(vbState)) {
    logLabelValue(gr ? "Verified Boot" : "Verified Boot",
            gr ? "GREEN: δηλώνεται από το Android, όχι ανεξάρτητη επιβεβαίωση"
               : "GREEN: OS-reported, not independently attested");
} else {
    logLabelValue(gr ? "Verified Boot" : "Verified Boot",
            gr ? "Μη διαθέσιμη ή μη αναγνωρισμένη κατάσταση"
               : "Unavailable or unrecognized state");
}
logInfo(gr ? "Δεν εκδόθηκε αυθαίρετος συνολικός δείκτης ασφάλειας."
           : "No arbitrary whole-device security score was issued.");

appendHtml("<br>");
logOk(gr ? "Το Lab 24 ολοκληρώθηκε (απογραφή προσβάσιμων ενδείξεων)."
         : "Lab 24 finished (accessible indicators inventoried).");
logInfo(gr ? "Δεν πιστοποιήθηκε συνολικά η ασφάλεια ή η ακεραιότητα της συσκευής."
           : "Overall device security and integrity were not certified.");
logLine();
}


// ============================================================
// LAB 24 — INTERNAL HELPERS
// ============================================================
private boolean lab24_fileExists(String path) {
try { return new File(path).exists(); }
catch (Throwable t) { return false; }
}

private List<String> lab24_getInstalledPackagesLower() {
List<String> out = new ArrayList<>();
try {
PackageManager pm = getPackageManager();
List<ApplicationInfo> apps = pm.getInstalledApplications(0);
if (apps != null) {
for (ApplicationInfo ai : apps) {
String p = ai.packageName;
if (p != null) out.add(p.toLowerCase(Locale.US));
}
}
} catch (Throwable ignore) {}
return out;
}

private boolean lab24_canExecSu() {
java.lang.Process p = null;
try {
p = Runtime.getRuntime().exec(new String[]{"su", "-c", "id"});
BufferedReader br =
new BufferedReader(
new InputStreamReader(p.getInputStream()));
String line = br.readLine();
br.close();
return line != null &&
line.toLowerCase(Locale.US).contains("uid=0");
} catch (Throwable t) {
return false;
} finally {
if (p != null) try { p.destroy(); } catch (Throwable ignore) {}
}
}

private String lab24_execFirstLine(String cmd) {
java.lang.Process p = null;
try {
p = Runtime.getRuntime().exec(cmd);
BufferedReader br =
new BufferedReader(
new InputStreamReader(p.getInputStream()));
String line = br.readLine();
br.close();
return line != null ? line.trim() : null;
} catch (Throwable t) {
return null;
} finally {
if (p != null) try { p.destroy(); } catch (Throwable ignore) {}
}
}

private String lab24_getProp(String key) {
String v = lab24_execFirstLine("getprop " + key);
if (v == null) return null;
v = v.trim();
return v.isEmpty() ? null : v.toLowerCase(Locale.US);
}

private String lab24_readOneLine(String path) {
BufferedReader br = null;
try {
br = new BufferedReader(new FileReader(new File(path)));
return br.readLine();
} catch (Throwable t) {
return null;
} finally {
if (br != null) try { br.close(); } catch (Throwable ignore) {}
}
}

// ============================================================
// LAB 24 — MAGISK STEALTH HEURISTICS (HONEST / HEURISTIC ONLY)
// Detects strong indicators of hidden root environments.
// Does NOT claim certainty.
// ============================================================
private int lab24_magiskStealthScore(List<String> findings) {

    int score = 0;

    // --------------------------------------------------------
    // 1) Zygisk / denylist style property hints
    // --------------------------------------------------------
    try {
        String v;

        v = lab24_getProp("ro.dalvik.vm.native.bridge");
        if (v != null && !v.isEmpty() && !"0".equals(v)) {
            score += 10;
            findings.add("native.bridge is set: " + v);
        }

        v = lab24_getProp("init.svc.magiskd");
        if (v != null) {
            score += 35;
            findings.add("init.svc.magiskd=" + v);
        }

        v = lab24_getProp("persist.magisk.hide");
        if (v != null) {
            score += 20;
            findings.add("persist.magisk.hide detected");
        }

    } catch (Throwable ignore) {}

    // --------------------------------------------------------
    // 2) Typical Magisk / overlay / mirror traces
    // --------------------------------------------------------
    String[] paths = {
            "/sbin/.magisk",
            "/dev/.magisk_unblock",
            "/cache/.magisk",
            "/data/adb/magisk",
            "/data/adb/modules",
            "/data/adb/service.d",
            "/data/adb/post-fs-data.d",
            "/debug_ramdisk",
            "/dev/zygisk",
            "/metadata/magisk"
    };

    for (String p : paths) {
        try {
            if (lab24_fileExists(p)) {
                score += 20;
                findings.add("suspicious root path: " + p);
            }
        } catch (Throwable ignore) {}
    }

    // --------------------------------------------------------
    // 3) Mount table traces
    // --------------------------------------------------------
    try {
        String mounts = lab24_readWholeFile("/proc/self/mounts");
        if (mounts != null) {
            String m = mounts.toLowerCase(Locale.US);

            if (m.contains("magisk")) {
                score += 35;
                findings.add("/proc/self/mounts contains magisk");
            }

            if (m.contains("/data/adb/modules")) {
                score += 25;
                findings.add("mounts reference /data/adb/modules");
            }

            if (m.contains("overlay") && m.contains("/system")) {
                score += 10;
                findings.add("overlay mount affecting /system detected");
            }
        }
    } catch (Throwable ignore) {}

    // --------------------------------------------------------
    // 4) /proc/* cmdline / maps traces (best effort)
    // --------------------------------------------------------
    try {
        String maps = lab24_readWholeFile("/proc/self/maps");
        if (maps != null) {
            String mm = maps.toLowerCase(Locale.US);

            if (mm.contains("zygisk")) {
                score += 25;
                findings.add("/proc/self/maps contains zygisk");
            }

            if (mm.contains("magisk")) {
                score += 25;
                findings.add("/proc/self/maps contains magisk");
            }
        }
    } catch (Throwable ignore) {}

    // --------------------------------------------------------
    // 5) Package hiding paradox:
    // no Magisk package, but strong root shell / adb module traces
    // --------------------------------------------------------
    try {
        boolean shellRoot = lab24_canExecSu();
        boolean magiskPkg = false;

        List<String> installed = lab24_getInstalledPackagesLower();
        for (String p : installed) {
            if (p == null) continue;
            if (p.contains("magisk")) {
                magiskPkg = true;
                break;
            }
        }

        boolean adbModules =
                lab24_fileExists("/data/adb/modules") ||
                lab24_fileExists("/data/adb/service.d") ||
                lab24_fileExists("/data/adb/post-fs-data.d");

        if (shellRoot && adbModules && !magiskPkg) {
            score += 30;
            findings.add("root shell + /data/adb traces present without visible Magisk package");
        }

    } catch (Throwable ignore) {}

    return Math.min(score, 100);
}

private String lab24_readWholeFile(String path) {
    BufferedReader br = null;
    try {
        br = new BufferedReader(new FileReader(new File(path)));
        StringBuilder sb = new StringBuilder();
        String line;
        int lines = 0;

        while ((line = br.readLine()) != null && lines < 400) {
            sb.append(line).append('\n');
            lines++;
        }

        return sb.toString();
    } catch (Throwable ignore) {
        return null;
    } finally {
        try { if (br != null) br.close(); } catch (Throwable ignore) {}
    }
}

